 const profilesContent=<div className="gn-profiles"><div className="onboarding-banner"><div className="onboarding-icon"><PenLine size={31}/></div><div><h2>{tr('Erst das Alphabet, dann immer echter.')}</h2><p>{tr('Stufe 1 ist jeder Buchstabe einzeln – danach ist die Schrift schon nutzbar. Zahlen, dein Schreibrhythmus und echte Buchstabenverbindungen machen sie Stufe für Stufe natürlicher.')}</p><p className="fine-print">{tr('Keine gemischten Originalwörter, keine automatisch zerschnittenen Foto-Buchstaben und keine fremde Demo-Schrift in deinen Wörtern.')}</p></div></div><div className="profile-grid"><article className="profile-card create-profile"><span className="round-icon"><Plus size={23}/></span><h3>{tr('Schritt 1: Handschrift benennen')}</h3><p>{tr('Danach beginnt automatisch die geführte Eingabe von a–z und A–Z.')}</p><label className="sr-only" htmlFor="profile-name">{tr('Name der Handschrift')}</label><input id="profile-name" maxLength={100} placeholder="z. B. Meine Alltagsschrift" value={profileName} onChange={e=>setProfileName(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')createProfile();}}/><button className="button primary" onClick={createProfile}><ArrowRight size={16}/>{tr('Handschrift einarbeiten')}</button></article>{library.profiles.map(p=>{const count=Array.from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ').filter(c=>p.glyphs[c]?.some(g=>g.source==='pen')).length,level=currentLevel(p);return <article className="profile-card" key={p.id}><div className="profile-preview"><span>Aa</span></div><h3>{p.name}</h3><p>{count<52?tr('{n}/52 Buchstaben geschrieben',{n:count}):tr('Stufe {n} von 5 erreicht',{n:level})}</p><progress max={count<52?52:5} value={count<52?count:level} aria-label={count<52?tr('{n} von 52 Klein- und Großbuchstaben',{n:count}):tr('Stufe {n} von 5',{n:level})}/><div className="button-row"><button className={`button ${level<5||count<52?'primary':''}`} onClick={()=>setTrain(p.id)}>{count===52?<><ListChecks size={15}/>{level<5?tr('Weiter mit Stufe {n}',{n:level+1}):tr('Stufen & verbessern')}</>:<><PenLine size={15}/>{tr('Einrichtung fortsetzen')}</>}</button>{count===52&&<button className={`button ${level>=5?'primary':''}`} onClick={()=>{setSetting('profileId',p.id);setView('studio');}}><Check size={15}/>{tr('Verwenden')}</button>}<button className="icon-button" aria-label={tr('{name} löschen',{name:p.name})} onClick={()=>{if(confirm(tr('Handschrift „{name}“ löschen? Dokumente mit diesem Profil wechseln zur Demo-Schrift. Sichere das Studio vorher, falls du sie behalten möchtest.',{name:p.name}))){setLibrary(l=>l?{...l,profiles:l.profiles.filter(x=>x.id!==p.id),notes:l.notes.map(n=>n.settings.profileId===p.id?{...n,settings:{...n.settings,profileId:'demo'},updated:new Date().toISOString()}:n),deleted:{...l.deleted,[p.id]:new Date().toISOString()}}:l);}}}><Trash2 size={16}/></button></div></article>;})}<article className="profile-card demo-card"><div className="profile-preview demo-lettering">{tr('Hallo, du.')}</div><h3>{tr('Studio-Schrift')}</h3><p>{tr('Eine Beispielschrift zum Ausprobieren.')}</p><span className="status-tag">{tr('Demo · keine persönliche Analyse')}</span><button className="button" onClick={()=>{setSetting('profileId','demo');setView('studio');}}>{tr('Im Studio verwenden')}<ArrowRight size={15}/></button></article></div></div>;
 if(view!=='studio')return <div className="app-shell view-library"><LibraryShell view={view} library={library} saveStatus={saveStatus} setView={setView} update={fn=>setLibrary(l=>l?fn(l):l)} openNote={openNote} createNote={createNote} photoImport={folderId=>{createNote(folderId);setPhotoText(true);}} lecture={()=>setLecture(true)} openSettings={()=>setModal('settings')} openHelp={()=>setModal('help')} openStudio={()=>setView('studio')} notify={notify}>{profilesContent}</LibraryShell>{overlays}</div>;
