  <li className={`ws-step ${answerCount?'done':answerSlots?'now':''}`}><div className="ws-step-head"><span className="ws-num">{answerCount?<Check size={14}/>:2}</span><div><strong>{tr('Antworten')}</strong><small>{answerCount?tr('{a} von {b} Antworten eingefügt',{a:answerCount,b:answerSlots}):tr('Von der KI holen oder selbst eintippen')}</small></div></div><button className="button primary ws-ai" disabled={!answerSlots} onClick={()=>{setAiReply('');setAiHelp(true);}}><Sparkles size={16}/>{tr('Mit KI ausfüllen')}</button><div className="ws-own"><button className="ws-own-toggle" aria-expanded={ownOpen} onClick={()=>setOwnOpen(o=>!o)}>{tr('Antworten selbst eintippen')}<ChevronDown size={14} style={{transform:ownOpen?'rotate(180deg)':undefined}}/></button>{ownOpen&&<div className="sp-textbox"><label className="sr-only" htmlFor="source-text">{tr('Text zum Umwandeln')}</label><textarea id="source-text" placeholder={worksheetMode?tr('Antworten der Reihe nach, eine pro Zeile – oder mit „;“ getrennt.\nTabellen als | Spalte | Spalte |\nName und Datum werden ausgelassen.'):tr('Was möchtest du festhalten? Schreib deinen Text hier hinein …')} maxLength={100000} value={note.text} onChange={e=>changeNote({...note,text:e.target.value},false)}/>{note.text&&<button className="sp-clear" aria-label={tr('Ganzen Text löschen')} title={tr('Ganzen Text löschen (rückgängig machbar)')} onClick={()=>changeNote({...note,text:''})}><X size={14}/></button>}</div>}</div></li>
